中级写法，先分别 计算 每一行的 a-e 是否和你输入的一致，然后汇总看结果
select * , `cal_a` + cal_b + cal_c + cal_d + cal_e `cal` from
(
select
id ,
if(a = a1, 1, 0) `cal_a`,
if(b = b1, 1, 0) `cal_b`,
if(c = c1, 1, 0) `cal_c`,
if(d = d1, 1, 0) `cal_d`,
if(e = e1, 1, 0) `cal_e`,
...
) a
where `cal` >=3

